package com.yonwiplugins.herbistats;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Stroke;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the route the theoretical best is measured against - the shortest walkable path to the next
 * search spot - so the number on the panel can be checked against what it is actually claiming.
 *
 * <p>Off by default, since Herbi AFK already draws a path to the next spot and two sets of lines on
 * one screen helps nobody.
 */
class HerbiPathOverlay extends Overlay
{
	private static final Stroke STROKE = new BasicStroke(2f);

	private final Client client;
	private final HerbiStatsPlugin plugin;
	private final HerbiStatsConfig config;

	@Inject
	private HerbiPathOverlay(Client client, HerbiStatsPlugin plugin, HerbiStatsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showPathToTarget())
		{
			return null;
		}

		final List<WorldPoint> path = plugin.getPathToTarget();

		if (path.isEmpty())
		{
			return null;
		}

		graphics.setStroke(STROKE);
		graphics.setColor(config.pathColor());

		Point previous = canvasPoint(client.getLocalPlayer() == null
			? null
			: client.getLocalPlayer().getWorldLocation());

		for (WorldPoint step : path)
		{
			final Point current = canvasPoint(step);

			if (previous != null && current != null)
			{
				graphics.drawLine(previous.getX(), previous.getY(), current.getX(), current.getY());
			}

			// A step off the edge of the viewport breaks the line rather than dragging it across
			// the screen to somewhere the player is not going.
			previous = current;
		}

		return null;
	}

	@SuppressWarnings("deprecation")
	private Point canvasPoint(WorldPoint point)
	{
		if (point == null || point.getPlane() != client.getPlane())
		{
			return null;
		}

		final LocalPoint local = LocalPoint.fromWorld(client, point);

		return local == null ? null : Perspective.localToCanvas(client, local, point.getPlane());
	}
}

