package com.yonwiplugins.herbistats;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Constants;
import net.runelite.api.coords.WorldPoint;

/**
 * Breadth first search across the loaded scene's collision map, giving the number of steps a player
 * actually has to take to reach a spot rather than how far away it looks.
 *
 * <p>Herbiboar spots sit behind swamp, rocks and mushroom clusters, so a straight line badly
 * understates several legs. The search stops on any tile beside the target, since the target itself
 * is an object and cannot be stood on.
 *
 * <p>Not thread safe: the scratch buffers are reused between searches to keep per-tick allocation
 * down, and everything here runs on the client thread.
 */
class HerbiPathfinder
{
	private static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION
		| CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;

	// Cardinals first, so a reconstructed path prefers straight lines over stair-stepping.
	private static final int[] DX = {0, 1, 0, -1, 1, 1, -1, -1};
	private static final int[] DY = {1, 0, -1, 0, 1, -1, -1, 1};
	private static final int[] SIDE = {
		CollisionDataFlag.BLOCK_MOVEMENT_NORTH,
		CollisionDataFlag.BLOCK_MOVEMENT_EAST,
		CollisionDataFlag.BLOCK_MOVEMENT_SOUTH,
		CollisionDataFlag.BLOCK_MOVEMENT_WEST,
		CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST,
		CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST,
		CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST,
		CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST,
	};

	private static final int SIZE = Constants.SCENE_SIZE;
	private static final int TILES = SIZE * SIZE;
	private static final int UNVISITED = -1;
	private static final int ROOT = -2;

	private final int[] parent = new int[TILES];
	private final int[] queue = new int[TILES];

	/**
	 * Walks the collision map from one point to another.
	 *
	 * @return the tiles the player must step through to stand beside the target, empty when the
	 *         target is outside the loaded scene or walled off
	 */
	@SuppressWarnings("deprecation")
	List<WorldPoint> path(Client client, WorldPoint from, WorldPoint to)
	{
		// getCollisionMaps/getBaseX moved onto WorldView in later clients, but this builds against
		// latest.release and the deprecated calls exist either side of that move.
		if (from == null || to == null || from.getPlane() != to.getPlane())
		{
			return Collections.emptyList();
		}

		final CollisionData[] maps = client.getCollisionMaps();
		final int plane = from.getPlane();

		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return Collections.emptyList();
		}

		final int baseX = client.getBaseX();
		final int baseY = client.getBaseY();

		final int startX = from.getX() - baseX;
		final int startY = from.getY() - baseY;
		final int goalX = to.getX() - baseX;
		final int goalY = to.getY() - baseY;

		if (outside(startX, startY) || outside(goalX, goalY))
		{
			return Collections.emptyList();
		}

		final int[][] flags = maps[plane].getFlags();

		Arrays.fill(parent, UNVISITED);

		int head = 0;
		int tail = 0;
		final int start = index(startX, startY);
		parent[start] = ROOT;
		queue[tail++] = start;

		while (head < tail)
		{
			final int current = queue[head++];
			final int cx = current % SIZE;
			final int cy = current / SIZE;

			// The target is an object, so standing next to it is as close as anyone gets.
			if (Math.abs(cx - goalX) <= 1 && Math.abs(cy - goalY) <= 1)
			{
				return reconstruct(current, baseX, baseY, plane);
			}

			for (int dir = 0; dir < DX.length; dir++)
			{
				final int nx = cx + DX[dir];
				final int ny = cy + DY[dir];

				if (outside(nx, ny))
				{
					continue;
				}

				final int next = index(nx, ny);

				if (parent[next] != UNVISITED)
				{
					continue;
				}

				if ((flags[cx][cy] & SIDE[dir]) != 0 || (flags[nx][ny] & BLOCKED) != 0)
				{
					continue;
				}

				parent[next] = current;
				queue[tail++] = next;
			}
		}

		return Collections.emptyList();
	}

	/**
	 * Steps needed to reach the target, or -1 when no route through the loaded scene was found.
	 */
	int steps(Client client, WorldPoint from, WorldPoint to)
	{
		final List<WorldPoint> path = path(client, from, to);
		return path.isEmpty() ? -1 : path.size();
	}

	private List<WorldPoint> reconstruct(int end, int baseX, int baseY, int plane)
	{
		final List<WorldPoint> path = new ArrayList<>();

		for (int at = end; at != ROOT; at = parent[at])
		{
			path.add(new WorldPoint(baseX + at % SIZE, baseY + at / SIZE, plane));
		}

		// Drop the tile the player is already standing on; it costs no steps.
		if (!path.isEmpty())
		{
			path.remove(path.size() - 1);
		}

		Collections.reverse(path);
		return path;
	}

	private static boolean outside(int x, int y)
	{
		return x < 0 || y < 0 || x >= SIZE || y >= SIZE;
	}

	private static int index(int x, int y)
	{
		return y * SIZE + x;
	}
}

