package com.yonwiplugins.herbistats;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(HerbiStatsConfig.GROUP)
public interface HerbiStatsConfig extends Config
{
	String GROUP = "herbistats";

	@ConfigSection(
		name = "Panel",
		description = "Where and when the stats panel appears",
		position = 0
	)
	String panelSection = "panel";

	@ConfigSection(
		name = "Rate stats",
		description = "Throughput: catches, loot and experience per hour",
		position = 1
	)
	String rateSection = "rates";

	@ConfigSection(
		name = "Trail stats",
		description = "Per-trail timings",
		position = 2
	)
	String trailSection = "trails";

	@ConfigSection(
		name = "Idle time",
		description = "Game ticks spent stationary when movement was possible",
		position = 3
	)
	String efficiencySection = "efficiency";

	@ConfigSection(
		name = "Route optimality",
		description = "Observed trail duration measured against a computed theoretical lower bound",
		position = 4
	)
	String routeSection = "route";

	// ------------------------------------------------------------------ panel

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show stats panel",
		description = "Draw the Herbi Stats panel. Stats keep accruing either way",
		position = 0,
		section = panelSection
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayVisibility",
		name = "Show panel",
		description = "How much of the time the panel stays on screen",
		position = 1,
		section = panelSection
	)
	default OverlayVisibility overlayVisibility()
	{
		return OverlayVisibility.IN_AREA;
	}

	@ConfigItem(
		keyName = "timeTracking",
		name = "Session clock",
		description = "Which ticks count towards the session timer, and so towards every per-hour rate",
		position = 2,
		section = panelSection
	)
	default TimeTracking timeTracking()
	{
		return TimeTracking.IN_AREA;
	}

	@ConfigItem(
		keyName = "trailTimeUnit",
		name = "Trail times in",
		description = "Report trail durations as game ticks or as seconds",
		position = 3,
		section = panelSection
	)
	default TrailTimeUnit trailTimeUnit()
	{
		return TrailTimeUnit.TICKS;
	}

	@ConfigItem(
		keyName = "showSessionTime",
		name = "Session time",
		description = "Show how long the session clock has been running",
		position = 4,
		section = panelSection
	)
	default boolean showSessionTime()
	{
		return true;
	}

	@ConfigItem(
		keyName = "panelDividers",
		name = "Group stats by",
		description = "How the panel separates rate, trail and efficiency stats, following the same"
			+ " split as the sections below",
		position = 5,
		section = panelSection
	)
	default PanelDividers panelDividers()
	{
		return PanelDividers.HEADINGS;
	}

	// ------------------------------------------------------------------ rates

	@ConfigItem(
		keyName = "showCatches",
		name = "Catches",
		description = "Show the number of herbiboars harvested this session",
		position = 0,
		section = rateSection
	)
	default boolean showCatches()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCatchesPerHour",
		name = "Catches/hr",
		description = "Show herbiboars harvested per hour",
		position = 1,
		section = rateSection
	)
	default boolean showCatchesPerHour()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showLoot",
		name = "Loot value",
		description = "Show the total Grand Exchange value of the herbs harvested",
		position = 2,
		section = rateSection
	)
	default boolean showLoot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showGpPerHour",
		name = "GP/hr",
		description = "Show loot value per hour",
		position = 3,
		section = rateSection
	)
	default boolean showGpPerHour()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showAverageLoot",
		name = "Average loot",
		description = "Show the average value of a single harvest",
		position = 4,
		section = rateSection
	)
	default boolean showAverageLoot()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showHunterXp",
		name = "Hunter XP",
		description = "Show Hunter experience gained this session",
		position = 5,
		section = rateSection
	)
	default boolean showHunterXp()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showHunterXpPerHour",
		name = "Hunter XP/hr",
		description = "Show Hunter experience per hour",
		position = 6,
		section = rateSection
	)
	default boolean showHunterXpPerHour()
	{
		return true;
	}

	// ----------------------------------------------------------------- trails

	@ConfigItem(
		keyName = "showCurrentTrail",
		name = "Current trail",
		description = "Show how long the trail in progress has been running",
		position = 0,
		section = trailSection
	)
	default boolean showCurrentTrail()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showLastTrail",
		name = "Last trail",
		description = "Show how long the previous completed trail took",
		position = 1,
		section = trailSection
	)
	default boolean showLastTrail()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBestTrail",
		name = "Best trail",
		description = "Show the fastest completed trail, with the number of search spots it had",
		position = 2,
		section = trailSection
	)
	default boolean showBestTrail()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showAverageTrail",
		name = "Average trail",
		description = "Show the mean length of a completed trail",
		position = 3,
		section = trailSection
	)
	default boolean showAverageTrail()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTrailsLost",
		name = "Trails lost",
		description = "Show how many trails ended without a harvest",
		position = 4,
		section = trailSection
	)
	default boolean showTrailsLost()
	{
		return false;
	}

	// ------------------------------------------------------------- efficiency

	@ConfigItem(
		keyName = "showTicksLost",
		name = "Idle ticks (trail)",
		description = "Count of game ticks during a trail where you were stationary and not stood at"
			+ " the spot being searched",
		position = 0,
		section = efficiencySection
	)
	default boolean showTicksLost()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showSessionTicksLost",
		name = "Idle ticks (session)",
		description = "The same count over every tracked tick, so turnaround between one trail ending"
			+ " and the next beginning is included",
		position = 1,
		section = efficiencySection
	)
	default boolean showSessionTicksLost()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showTicksLostPerCatch",
		name = "Idle ticks per catch",
		description = "Mean idle ticks per herbiboar harvested",
		position = 2,
		section = efficiencySection
	)
	default boolean showTicksLostPerCatch()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showEfficiency",
		name = "Active tick ratio (trail)",
		description = "Proportion of trail ticks that were not idle, as a percentage",
		position = 3,
		section = efficiencySection
	)
	default boolean showEfficiency()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showSessionEfficiency",
		name = "Active tick ratio (session)",
		description = "The same proportion over every tracked tick, turnaround included",
		position = 4,
		section = efficiencySection
	)
	default boolean showSessionEfficiency()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showTrailMinimum",
		name = "Theoretical lower bound",
		description = "Fewest ticks the trail in progress could physically have taken: the walkable"
			+ " route to each revealed spot at running pace, plus the measured search, reaction and"
			+ " harvest costs. Validated against real trails as a bound never once beaten",
		position = 0,
		section = routeSection
	)
	default boolean showTrailMinimum()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showAboveMinimum",
		name = "Excess ticks over bound",
		description = "Observed ticks minus the lower bound, summed over the session",
		position = 1,
		section = routeSection
	)
	default boolean showAboveMinimum()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showRouteEfficiency",
		name = "Optimality ratio",
		description = "Lower bound divided by observed ticks. 100% means every trail was run at the"
			+ " physical minimum; the gap below it is recoverable time",
		position = 2,
		section = routeSection
	)
	default boolean showRouteEfficiency()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showPathToTarget",
		name = "Draw shortest path",
		description = "Draw the walkable route the theoretical best is measured against. Off by"
			+ " default because Herbi AFK already draws a path to the next spot",
		position = 3,
		section = routeSection
	)
	default boolean showPathToTarget()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "pathColor",
		name = "Path colour",
		description = "Colour of the shortest-path line",
		position = 4,
		section = routeSection
	)
	default Color pathColor()
	{
		return new Color(0x4C, 0xAF, 0x50, 0xC0);
	}

	@Range(min = 0, max = 5)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "idleGraceTicks",
		name = "Idle grace",
		description = "Extra ticks of standing still to forgive on top of the one tick that is"
			+ " always excluded, since a revealed trail and the first step away can never share a"
			+ " tick. 0 holds you to the fastest transition the game allows",
		position = 3,
		section = efficiencySection
	)
	default int idleGraceTicks()
	{
		return 0;
	}
}

