package com.yonwiplugins.herbistats;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import net.runelite.api.Constants;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

import static net.runelite.api.MenuAction.RUNELITE_OVERLAY;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

class HerbiStatsOverlay extends OverlayPanel
{
	private static final String RESET = "Reset";
	private static final String TARGET = "Herbi Stats overlay";

	private static final Color GOOD = new Color(0x4CAF50);
	private static final Color OKAY = new Color(0xFFC107);
	private static final Color POOR = new Color(0xF4511E);
	private static final Color HEADING = new Color(0x9E9E9E);

	private final HerbiStatsPlugin plugin;
	private final HerbiStatsConfig config;

	@Inject
	private HerbiStatsOverlay(HerbiStatsPlugin plugin, HerbiStatsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, TARGET);
		addMenuEntry(RUNELITE_OVERLAY, RESET, TARGET, e -> plugin.resetSession());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || !isVisibleNow())
		{
			return null;
		}

		final HerbiStatsSession session = plugin.getSession();

		if (!session.isStarted())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Herbi Stats")
			.color(Color.WHITE)
			.build());

		// The session clock heads the panel rather than joining a group - it is the frame every
		// other figure is measured against.
		if (config.showSessionTime())
		{
			panelComponent.getChildren().add(row("Time", formatDuration(session.getDurationMillis())));
		}

		section("Rates", rateRows(session));
		section("Trails", trailRows(session));
		section("Idle time", idleRows(session));
		section("Route optimality", routeRows(session));

		panelComponent.setPreferredSize(new Dimension(168, 0));
		return super.render(graphics);
	}

	private boolean isVisibleNow()
	{
		switch (config.overlayVisibility())
		{
			case IN_AREA:
				return plugin.isInHerbiboarArea();
			case ON_TRAIL:
				return plugin.isTrailActive();
			case ALWAYS:
			default:
				return true;
		}
	}

	/**
	 * Adds a group of rows under whatever separator the player asked for, skipping the separator
	 * entirely when the group has nothing to show or nothing precedes it.
	 */
	private void section(String heading, List<LineComponent> rows)
	{
		if (rows.isEmpty())
		{
			return;
		}

		final PanelDividers dividers = config.panelDividers();

		if (dividers == PanelDividers.HEADINGS)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(heading)
				.leftColor(HEADING)
				.build());
		}
		else if (dividers == PanelDividers.SPACING && panelComponent.getChildren().size() > 1)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("").build());
		}

		panelComponent.getChildren().addAll(rows);
	}

	private List<LineComponent> rateRows(HerbiStatsSession session)
	{
		final List<LineComponent> rows = new ArrayList<>();

		if (config.showCatches())
		{
			rows.add(row("Catches", Integer.toString(session.getCatches())));
		}

		if (config.showCatchesPerHour())
		{
			rows.add(row("Catches/hr", Integer.toString(session.getCatchesPerHour())));
		}

		if (config.showLoot())
		{
			rows.add(row("Loot", formatGp(session.getLootValue())));
		}

		if (config.showGpPerHour())
		{
			rows.add(row("GP/hr", formatGp(session.getGpPerHour())));
		}

		if (config.showAverageLoot())
		{
			rows.add(row("Loot/catch", formatGp(session.getAverageLootValue())));
		}

		if (config.showHunterXp())
		{
			rows.add(row("Hunter XP", formatGp(session.getHunterXp())));
		}

		if (config.showHunterXpPerHour())
		{
			rows.add(row("XP/hr", formatGp(session.getHunterXpPerHour())));
		}

		return rows;
	}

	private List<LineComponent> trailRows(HerbiStatsSession session)
	{
		final List<LineComponent> rows = new ArrayList<>();

		if (config.showCurrentTrail() && plugin.isTrailActive())
		{
			final int ticks = plugin.getCurrentTrailTicks();
			rows.add(row("Current", ticks < 0
				? "-"
				: trailTime(ticks) + " (" + plugin.getCurrentTrailSpots() + ")", GOOD));
		}

		if (config.showLastTrail() && session.getLastTrailTicks() >= 0)
		{
			rows.add(row("Last trail", trailTime(session.getLastTrailTicks())));
		}

		if (config.showBestTrail() && session.getBestTrailTicks() >= 0)
		{
			rows.add(row("Best trail", trailTime(session.getBestTrailTicks())
				+ " (" + session.getBestTrailSpots() + ")"));
		}

		if (config.showAverageTrail() && session.getAverageTrailTicks() >= 0)
		{
			rows.add(row("Avg trail", trailTime(session.getAverageTrailTicks())));
		}

		if (config.showTrailsLost())
		{
			rows.add(row("Trails lost", Integer.toString(session.getTrailsLost())));
		}

		return rows;
	}

	/**
	 * Time stood still when the player could have been moving.
	 */
	private List<LineComponent> idleRows(HerbiStatsSession session)
	{
		final List<LineComponent> rows = new ArrayList<>();

		if (config.showTicksLost())
		{
			rows.add(row("Idle (trail)", session.getLostTicks() + "t"));
		}

		if (config.showSessionTicksLost())
		{
			rows.add(row("Idle (session)", session.getSessionLostTicks() + "t"));
		}

		if (config.showTicksLostPerCatch() && session.getCatches() > 0)
		{
			rows.add(row("Idle/catch", String.format("%.1ft", session.getLostTicksPerCatch())));
		}

		final int efficiency = session.getEfficiencyPercent();

		if (config.showEfficiency() && efficiency >= 0)
		{
			rows.add(row("Active (trail)", efficiency + "%", efficiencyColor(efficiency)));
		}

		final int sessionEfficiency = session.getSessionEfficiencyPercent();

		if (config.showSessionEfficiency() && sessionEfficiency >= 0)
		{
			rows.add(row("Active (session)", sessionEfficiency + "%", efficiencyColor(sessionEfficiency)));
		}

		return rows;
	}

	/**
	 * How the running compares with the quickest the same trail could have been walked.
	 */
	private List<LineComponent> routeRows(HerbiStatsSession session)
	{
		final List<LineComponent> rows = new ArrayList<>();

		final int minimum = plugin.getCurrentTrailMinimum();

		if (config.showTrailMinimum() && minimum >= 0)
		{
			final int elapsed = plugin.getCurrentTrailTicks();
			rows.add(row("Lower bound", trailTime(minimum), elapsed > minimum ? POOR : GOOD));
		}

		final int above = session.getAboveMinimumTicks();

		if (config.showAboveMinimum() && above >= 0)
		{
			rows.add(row("Excess", above + "t"));
		}

		final int routeEfficiency = session.getRouteEfficiencyPercent();

		if (config.showRouteEfficiency() && routeEfficiency >= 0)
		{
			rows.add(row("Optimality", routeEfficiency + "%", efficiencyColor(routeEfficiency)));
		}

		return rows;
	}

	private static LineComponent row(String left, String right)
	{
		return LineComponent.builder()
			.left(left)
			.right(right)
			.build();
	}

	private static LineComponent row(String left, String right, Color rightColor)
	{
		return LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build();
	}

	private static Color efficiencyColor(int percent)
	{
		if (percent >= 90)
		{
			return GOOD;
		}

		return percent >= 75 ? OKAY : POOR;
	}

	private String trailTime(int ticks)
	{
		if (config.trailTimeUnit() == TrailTimeUnit.SECONDS)
		{
			return String.format("%.1fs", ticks * Constants.GAME_TICK_LENGTH / 1000f);
		}

		return Integer.toString(ticks);
	}

	private static String formatGp(long amount)
	{
		return amount >= 100_000 || amount <= -100_000
			? QuantityFormatter.quantityToStackSize(amount)
			: QuantityFormatter.formatNumber(amount);
	}

	private static String formatDuration(long millis)
	{
		final long hours = TimeUnit.MILLISECONDS.toHours(millis);
		final long minutes = TimeUnit.MILLISECONDS.toMinutes(millis) % 60;
		final long seconds = TimeUnit.MILLISECONDS.toSeconds(millis) % 60;

		return hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, seconds)
			: String.format("%d:%02d", minutes, seconds);
	}
}

