@PluginDescriptor(
	name = "Herbi Stats",
	description = "Session statistics for Herbiboar hunting: catches/hr, GP/hr, trail times, ticks lost and efficiency",
	tags = {"herbiboar", "herbi", "hunter", "herblore", "fossil", "island", "stats", "efficiency", "tracker"}
)
@Slf4j
public class HerbiStatsPlugin extends Plugin
{
	/**
	 * The message the game prints the moment a herbiboar is successfully harvested. This is the
	 * only unambiguous signal that a trail ended in a catch rather than a lost trail.
	 */
	static final String HARVEST_MESSAGE = "You harvest herbs from the herbiboar, whereupon it escapes.";

	/**
	 * A distinctive fragment of the message shown when the trail is lost and the hunt has to be
	 * restarted: "The creature has successfully confused you with its tracks, leading you round in
	 * circles. You'll need to start again." Matched loosely so wording either side of it can drift
	 * without silently breaking the count.
	 */
	private static final String LOST_TRAIL_FRAGMENT = "confused you with its tracks";

	/**
	 * Matches the spam line printed for each herb that goes straight into a herb sack, e.g.
	 * "You put the Grimy guam leaf herb into your herb sack." When the sack swallows the loot it
	 * never touches the inventory, so these messages are the only record of it.
	 */
	private static final Pattern HERB_SACK_PATTERN = Pattern.compile(".+(Grimy .+?) herb.+");

	private static final int[] HERBIBOAR_REGIONS = {14652, 14651, 14908, 14907};

	/**
	 * The tunnels the herbiboar can end up hiding in, indexed by the finish varbit minus one.
	 */
	private static final WorldPoint[] END_LOCATIONS = {
		new WorldPoint(3693, 3798, 0),
		new WorldPoint(3702, 3808, 0),
		new WorldPoint(3703, 3826, 0),
		new WorldPoint(3710, 3881, 0),
		new WorldPoint(3700, 3877, 0),
		new WorldPoint(3715, 3840, 0),
		new WorldPoint(3751, 3849, 0),
		new WorldPoint(3685, 3869, 0),
		new WorldPoint(3681, 3863, 0),
	};

	/**
	 * Ticks to wait for the inventory to actually change after a harvest before giving up on
	 * attributing loot to it.
	 */
	private static final int LOOT_TIMEOUT_TICKS = 5;

	/**
	 * Ticks to keep a finished-looking trail open for. The varbits clear when the tunnel is
	 * searched, but the harvest animation runs for several ticks before the message that confirms
	 * it, so this has to outlast that. A new hunt starting closes the old trail out early anyway,
	 * making this only a backstop for the player wandering off mid-hunt.
	 */
	private static final int TRAIL_END_GRACE_TICKS = 25;

	/**
	 * How close the player has to be to a search spot for standing still to count as searching it
	 * rather than dawdling. The object occupies its own tile, so the player stands beside it.
	 */
	private static final int INTERACT_RANGE = 2;

	/**
	 * The reveal and the first step away can never land on the same tick: the trail varbit arrives,
	 * and the movement it prompts resolves on the tick after. Measured across real trails the best
	 * transitions cost exactly one tick and never zero, so this is a floor of the game rather than
	 * sloppiness, and is never counted against the player. The configured idle grace is slack on
	 * top of it.
	 */
	private static final int REVEAL_FLOOR_TICKS = 1;

	/**
	 * Ticks a search takes once the player is stood at the spot. Measured over 98 legs of real
	 * play, 89 of which took exactly this, so it is treated as a constant of the activity rather
	 * than something to estimate per trail.
	 */
	private static final int SEARCH_TICKS = 3;

	/**
	 * Tiles covered per tick while running. Running is a toggle rather than a sliding scale - out
	 * of energy the player drops to one tile a tick - and the theoretical best assumes they kept
	 * running throughout.
	 */
	private static final int RUNNING_TILES_PER_TICK = 2;

	/**
	 * Beyond this a distance is not a herbiboar leg but a scene that has not caught up, and costing
	 * it would poison the trail's target.
	 */
	private static final int MAX_LEG_TILES = 200;

	/**
	 * Ticks between the tunnel search resolving and the harvest landing. Nothing the player does
	 * shortens it, so it belongs in the theoretical best. Measured over 42 harvests: 41 took four
	 * ticks or more and the single three-tick reading never reproduced, so it is treated as a
	 * timing artefact rather than a floor anyone can hit.
	 */
	private static final int HARVEST_TICKS = 4;

	private static final int NO_TICK = -1;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HerbiStatsOverlay overlay;

	@Inject
	private HerbiPathOverlay pathOverlay;

	@Inject
	private HerbiStatsConfig config;

	@Inject
	private ItemManager itemManager;

	@Getter(AccessLevel.PACKAGE)
	private HerbiStatsSession session = new HerbiStatsSession();

	@Getter(AccessLevel.PACKAGE)
	private boolean inHerbiboarArea;

	/**
	 * Search spots whose incoming trail has been revealed on the trail currently being walked, in
	 * the order they were revealed - which is the order the player visits them.
	 */
	private final Set<HerbiSearchSpot> currentPath = new LinkedHashSet<>();

	/**
	 * The spot the player is currently headed for, or null once the hunt has reached the tunnels.
	 */
	private HerbiSearchSpot currentTarget;

	/**
	 * The quickest the trail so far could have been run, accumulated a leg at a time as each one is
	 * revealed. A leg costs the run to the spot at full pace plus the search and reaction ticks
	 * that cannot be avoided.
	 */
	private int trailMinimumTicks;

	/**
	 * Every target the running total has already been charged for. A set rather than just the last
	 * one, so a target that comes back into view can never be charged a second time.
	 */
	private final Set<Object> costedTargets = new HashSet<>();

	private final HerbiPathfinder pathfinder = new HerbiPathfinder();

	@Getter(AccessLevel.PACKAGE)
	private boolean trailActive;

	private int trailStartTick = NO_TICK;
	private int trailSpots;
	/**
	 * False once a trail is picked up midway through - after a hop or a login - where the elapsed
	 * time would be measured from the wrong place.
	 */
	private boolean trailTimed;
	/**
	 * A trail can only be considered finished once it has genuinely been under way, which guards
	 * against reading the gap between clicking a start object and the first trail appearing as an
	 * instantly lost trail.
	 */
	private boolean sawPathActive;
	/**
	 * Set when the varbits say the trail is over. Resolved a tick later so a harvest message
	 * arriving in the same tick gets to claim the trail as a catch first.
	 */
	private int pendingEndTick = NO_TICK;
	/**
	 * Blocks a fresh trail from being started off the tail end of the one just closed out. Released
	 * as soon as the hunting trail varbits read as idle again, which the game does once a hunt
	 * ends - the same reset the built-in Herbiboar plugin relies on to pick up the next trail.
	 */
	private boolean awaitingVarbitReset;

	/**
	 * Whether the previous look at the varbits found a hunt already under way. A trail is only
	 * timed when we watched it cross from idle into started, which is what separates a trail begun
	 * under our nose from one that was already running when we logged in or hopped. Defaults to
	 * true so an unobserved hunt is assumed to be mid-flight until the varbits prove otherwise.
	 */
	private boolean huntInProgress = true;

	private int idleRun;

	/**
	 * Where the player stood last tick, which is what movement is judged against.
	 */
	private WorldPoint lastPosition;

	/**
	 * Which tunnel the hunt ends at, once it has reached that stage. Zero at every other point.
	 */
	private int currentFinishId;

	private Multiset<Integer> inventorySnapshot;
	private int lootTimeoutTick = NO_TICK;

	private int lastHunterXp = -1;

	@Provides
	HerbiStatsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HerbiStatsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(pathOverlay);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				inHerbiboarArea = checkArea();
				lastHunterXp = client.getSkillExperience(Skill.HUNTER);
				updateTrailState();
			});
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(pathOverlay);
		resetTrail();
		inHerbiboarArea = false;
		inventorySnapshot = null;
		lastHunterXp = -1;
	}

	/**
	 * Throws away every accumulated statistic and starts counting again from zero.
	 */
	void resetSession()
	{
		session = new HerbiStatsSession();
		resetTrail();
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
			case LOGGING_IN:
			case CONNECTION_LOST:
				// The trail survives a hop, but our measurement of it does not.
				resetTrail();
				lastHunterXp = -1;
				lastPosition = null;
				inventorySnapshot = null;
				break;
			case LOADING:
				inHerbiboarArea = checkArea();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		updateTrailState();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (config.timeTracking() == TimeTracking.LOGGED_IN || inHerbiboarArea)
		{
			session.tick();
		}

		if (inHerbiboarArea)
		{
			// Costed here rather than off VarbitChanged: a reveal fires several varbit events in
			// one tick, and only on the tick boundary has the target settled on a single spot.
			if (trailActive)
			{
				costCurrentLeg();
			}

			trackIdleTick(trailActive);
		}

		if (pendingEndTick != NO_TICK && client.getTickCount() > pendingEndTick + TRAIL_END_GRACE_TICKS)
		{
			// The varbits went quiet and neither outcome message turned up in the grace period.
			abandonTrail();
		}

		if (inventorySnapshot != null && client.getTickCount() > lootTimeoutTick)
		{
			inventorySnapshot = null;
			lootTimeoutTick = NO_TICK;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final ChatMessageType type = event.getType();

		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.MESBOX)
		{
			return;
		}

		final String message = Text.removeTags(event.getMessage());

		if (HARVEST_MESSAGE.equals(message))
		{
			recordCatch();

			if (!collectHerbSackLoot(event.getTimestamp()))
			{
				armInventoryDiff();
			}

			return;
		}

		if (message.contains(LOST_TRAIL_FRAGMENT))
		{
			recordLostTrail();
			return;
		}

		if (log.isDebugEnabled()
			&& (message.toLowerCase().contains("herbiboar") || message.contains("tracks")))
		{
			log.debug("Herbiboar chat [{}]: {}", type, message);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.HUNTER)
		{
			return;
		}

		final int xp = event.getXp();

		if (lastHunterXp >= 0 && xp > lastHunterXp)
		{
			session.addHunterXp(xp - lastHunterXp);
		}

		lastHunterXp = xp;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (inventorySnapshot == null || event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		final Multiset<Integer> current = snapshot(event.getItemContainer());
		final Multiset<Integer> gained = Multisets.difference(current, inventorySnapshot);

		for (Multiset.Entry<Integer> entry : gained.entrySet())
		{
			addLoot(entry.getElement(), entry.getCount());
		}

		inventorySnapshot = null;
		lootTimeoutTick = NO_TICK;
	}

	// ----------------------------------------------------------- trail state

	/**
	 * Rebuilds what we know about the trail from the hunting trail varbits, following the same
	 * reading of them as RuneLite's built-in Herbiboar plugin.
	 */
	private void updateTrailState()
	{
		if (!inHerbiboarArea)
		{
			return;
		}

		boolean pathActive = false;

		for (HerbiSearchSpot spot : HerbiSearchSpot.values())
		{
			for (HerbiSearchSpot.Trail trail : spot.getTrails())
			{
				final int value = client.getVarbitValue(trail.getVarbitId());

				if (value == trail.getValue())
				{
					// This trail is laid out in front of the player right now, so the spot at the
					// end of it is the one they are on their way to.
					currentPath.add(spot);
					currentTarget = spot;
				}
				else if (value > 0)
				{
					pathActive = true;
				}
			}
		}

		// Non-zero once the last spot has been searched and the herbiboar is hiding in one of the
		// tunnels. No footprint trail is active during that leg, so this is what separates "walking
		// to the tunnel" from "the hunt is genuinely over".
		final int finishId = client.getVarbitValue(VarbitID.HUNTING_TRAIL_ENDS_FOSSIL);
		currentFinishId = finishId;

		final boolean started = client.getVarbitValue(VarbitID.HUNTING_TRAILS_USED_FOSSIL) > 0
			|| finishId > 0
			|| !currentPath.isEmpty();

		if (!started)
		{
			awaitingVarbitReset = false;
			huntInProgress = false;
			endOfHunt();
			return;
		}

		if (awaitingVarbitReset)
		{
			return;
		}

		// Captured before anything resets it, because it is what decides whether the trail about to
		// begin is one we watched start.
		final boolean freshHunt = !huntInProgress;

		if (freshHunt && trailActive)
		{
			// A new hunt has begun while the previous one never announced an outcome, so close the
			// old one out here rather than letting the two run together.
			abandonTrail();
			awaitingVarbitReset = false;
		}

		if (!trailActive)
		{
			beginTrail(freshHunt);
		}

		huntInProgress = true;

		if (pathActive)
		{
			sawPathActive = true;
		}

		trailSpots = Math.max(trailSpots, currentPath.size());

		// Only once the footprints have gone AND the tunnel stage has cleared is the hunt actually
		// over - either harvested, or lost.
		if (sawPathActive && !pathActive && finishId == 0)
		{
			endOfHunt();
		}
	}

	/**
	 * Charges the trail's theoretical best for the leg just revealed: the run from where the player
	 * stands to the spot the game has just pointed them at, plus the search and reaction ticks that
	 * no amount of skill removes.
	 *
	 * <p>Measured from where the player actually is rather than from where they ideally would be,
	 * so overshooting a spot is not then charged twice.
	 */
	private void costCurrentLeg()
	{
		final Object target = currentFinishId > 0 ? (Object) ("TUNNEL" + currentFinishId) : currentTarget;

		if (target == null || costedTargets.contains(target))
		{
			return;
		}

		final WorldPoint destination = targetLocation();
		final Player player = client.getLocalPlayer();

		if (destination == null || player == null)
		{
			return;
		}

		final WorldPoint at = player.getWorldLocation();

		// Herbiboar spots sit behind swamp and rock, so a straight line understates several legs.
		// Fall back to it only when the target is outside the loaded scene and cannot be walked.
		final int walked = pathfinder.steps(client, at, destination);
		final int tiles = walked >= 0 ? walked : at.distanceTo(destination);

		if (tiles < 0 || tiles > MAX_LEG_TILES)
		{
			return;
		}

		costedTargets.add(target);
		trailMinimumTicks += ceilDiv(tiles, RUNNING_TILES_PER_TICK) + SEARCH_TICKS + REVEAL_FLOOR_TICKS;

		log.debug("Leg to {}: {} tiles ({}), min so far {}", target, tiles,
			walked >= 0 ? "walked" : "straight-line fallback", trailMinimumTicks);
	}

	/**
	 * The route the player would take to their next target right now, for drawing it on screen.
	 */
	List<WorldPoint> getPathToTarget()
	{
		final WorldPoint destination = targetLocation();
		final Player player = client.getLocalPlayer();

		if (!trailActive || destination == null || player == null)
		{
			return Collections.emptyList();
		}

		return pathfinder.path(client, player.getWorldLocation(), destination);
	}

	private static int ceilDiv(int value, int divisor)
	{
		return (value + divisor - 1) / divisor;
	}

	/**
	 * The quickest the trail in progress could have been run so far, or -1 when there is nothing to
	 * compare against.
	 */
	int getCurrentTrailMinimum()
	{
		return trailActive && trailTimed && trailMinimumTicks > 0 ? trailMinimumTicks : NO_TICK;
	}

	/**
	 * The varbits have gone quiet, but the harvest animation still has a few ticks to run before
	 * the message that says how it went. The trail is held open for that, with nothing left to head
	 * towards - so those ticks are not blamed on a search spot the player finished with long ago.
	 */
	private void endOfHunt()
	{
		currentTarget = null;

		if (trailActive && pendingEndTick == NO_TICK)
		{
			pendingEndTick = client.getTickCount();
			// Charged once, here, because the harvest runs whether the trail was walked well or
			// badly and the trail's own clock keeps running through it.
			trailMinimumTicks += HARVEST_TICKS;
		}
	}

	/**
	 * @param fresh whether the hunt was watched crossing from idle into started, which is the only
	 *              case where the elapsed time means anything
	 */
	private void beginTrail(boolean fresh)
	{
		trailActive = true;
		trailStartTick = client.getTickCount();
		trailSpots = currentPath.size();
		idleRun = 0;
		sawPathActive = false;
		pendingEndTick = NO_TICK;
		// Searching the start object reveals the first trail straight away, so currentPath is never
		// empty here and cannot answer this on its own.
		trailTimed = fresh;
	}

	/**
	 * A harvest message is proof of a catch by itself, so the catch is recorded whether or not the
	 * trail was being followed. Trail tracking only decides whether a usable duration comes with
	 * it - a catch is never dropped because the varbit reading of the trail went astray.
	 */
	private void recordCatch()
	{
		final int ticks = trailActive && trailTimed ? client.getTickCount() - trailStartTick : -1;

		log.debug("Herbiboar caught: ticks={} spots={} trailTracked={}", ticks, trailSpots, trailActive);
		session.recordCatch(ticks, trailSpots);

		if (trailTimed)
		{
			session.recordRoute(ticks, trailMinimumTicks);
		}

		resetTrail();
		awaitingVarbitReset = true;
	}

	/**
	 * Like a catch, a lost trail announces itself in chat, so it is taken at its word rather than
	 * guessed at from how the varbits happen to settle.
	 */
	private void recordLostTrail()
	{
		log.debug("Trail lost after {} spots", trailSpots);
		session.recordTrailLost();

		resetTrail();
		awaitingVarbitReset = true;
	}

	/**
	 * Drops a trail that stopped without announcing either outcome - the player wandered off, or
	 * started a fresh track before harvesting the last one. Counted as neither a catch nor a loss,
	 * because we genuinely do not know which it was.
	 */
	private void abandonTrail()
	{
		if (!trailActive)
		{
			return;
		}

		log.debug("Trail dropped with no outcome message after {} spots", trailSpots);

		resetTrail();
		awaitingVarbitReset = true;
	}

	private void resetTrail()
	{
		trailActive = false;
		currentPath.clear();
		currentTarget = null;
		currentFinishId = 0;
		trailMinimumTicks = 0;
		costedTargets.clear();
		trailStartTick = NO_TICK;
		trailSpots = 0;
		trailTimed = false;
		sawPathActive = false;
		pendingEndTick = NO_TICK;
		idleRun = 0;
		// Assume a hunt could already be running until the varbits say otherwise, so a trail picked
		// up after a login or hop is not mistaken for one we watched from the start.
		huntInProgress = true;
	}

	/**
	 * Ticks elapsed on the trail in progress, or -1 when there is nothing to report.
	 */
	int getCurrentTrailTicks()
	{
		return trailActive && trailTimed ? client.getTickCount() - trailStartTick : NO_TICK;
	}

	int getCurrentTrailSpots()
	{
		return trailSpots;
	}

	// ------------------------------------------------------------ efficiency

	/**
	 * @param onTrail whether a trail is under way, which decides whether the tick counts towards
	 *                mid-trail idling or towards turnaround between trails
	 */
	private void trackIdleTick(boolean onTrail)
	{
		final Player player = client.getLocalPlayer();

		if (player == null)
		{
			return;
		}

		final WorldPoint at = player.getWorldLocation();
		final boolean moved = lastPosition != null && !lastPosition.equals(at);
		lastPosition = at;

		if (moved)
		{
			idleRun = 0;
			record(onTrail, false);
			return;
		}

		// Standing still only pays while the player is at the thing they are searching. The moment
		// the trail varbit fires the target moves on - which is exactly when the built-in Herbiboar
		// overlay re-points at the next object - so from that tick every further tick stood here is
		// one that could have been spent running, part way through a search animation or not.
		final WorldPoint target = onTrail ? targetLocation() : null;

		if (onTrail && (target == null || at.distanceTo(target) <= INTERACT_RANGE))
		{
			idleRun = 0;
			record(onTrail, false);
			return;
		}

		idleRun++;

		final boolean lost = idleRun > REVEAL_FLOOR_TICKS + config.idleGraceTicks();
		record(onTrail, lost);
	}

	private void record(boolean onTrail, boolean lost)
	{
		if (onTrail)
		{
			if (lost)
			{
				session.recordLostTick();
			}
			else
			{
				session.recordWorkedTick();
			}
		}
		else if (lost)
		{
			session.recordBetweenLostTick();
		}
		else
		{
			session.recordBetweenWorkedTick();
		}
	}

	/**
	 * Where the player is headed: the next search spot, or the tunnel once the hunt reaches it.
	 */
	private WorldPoint targetLocation()
	{
		if (currentFinishId > 0 && currentFinishId <= END_LOCATIONS.length)
		{
			return END_LOCATIONS[currentFinishId - 1];
		}

		return currentTarget == null ? null : currentTarget.getLocation();
	}

	// ------------------------------------------------------------------ loot

	/**
	 * Reads the herbs straight out of the herb sack messages printed alongside the harvest.
	 *
	 * @return true when this harvest went to a herb sack and has been accounted for
	 */
	private boolean collectHerbSackLoot(int timestamp)
	{
		boolean found = false;

		for (MessageNode node : client.getMessages())
		{
			if (node.getTimestamp() != timestamp || node.getType() != ChatMessageType.SPAM)
			{
				continue;
			}

			final Matcher matcher = HERB_SACK_PATTERN.matcher(node.getValue());

			if (!matcher.matches())
			{
				continue;
			}

			final List<ItemPrice> matches = itemManager.search(matcher.group(1));

			if (!matches.isEmpty())
			{
				addLoot(matches.get(0).getId(), 1);
				found = true;
			}
		}

		return found;
	}

	/**
	 * Records the inventory as it stands so the next change to it can be read as the harvest.
	 */
	private void armInventoryDiff()
	{
		inventorySnapshot = snapshot(client.getItemContainer(InventoryID.INV));
		lootTimeoutTick = client.getTickCount() + LOOT_TIMEOUT_TICKS;
	}

	private void addLoot(int itemId, int quantity)
	{
		final long value = (long) itemManager.getItemPrice(itemId) * quantity;
		session.addLoot(itemId, quantity, value);
	}

	private static Multiset<Integer> snapshot(ItemContainer container)
	{
		final Multiset<Integer> items = HashMultiset.create();

		if (container != null)
		{
			for (Item item : container.getItems())
			{
				items.add(item.getId(), item.getQuantity());
			}
		}

		return items;
	}

	// ------------------------------------------------------------------ area

	@SuppressWarnings("deprecation")
	private boolean checkArea()
	{
		// WorldView#getMapRegions would be the modern route, but WorldView has moved package
		// between client releases and this builds against latest.release. Client#getMapRegions is
		// deprecated yet present either side of that move, and is what the built-in Herbiboar
		// plugin still calls.
		final int[] mapRegions = client.getMapRegions();

		if (mapRegions == null)
		{
			return false;
		}

		for (int region : mapRegions)
		{
			for (int herbiboarRegion : HERBIBOAR_REGIONS)
			{
				if (region == herbiboarRegion)
				{
					return true;
				}
			}
		}

		return false;
	}
}

