package com.yonwiplugins.herbistats;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.Constants;

/**
 * Everything Herbi Stats counts for one hunting session.
 *
 * <p>Deliberately free of any RuneLite client state so the arithmetic behind every displayed
 * figure can be exercised directly in tests. {@link HerbiStatsPlugin} owns the single instance and
 * is the only thing that mutates it.
 */
@Getter
class HerbiStatsSession
{
	private static final long MILLIS_PER_HOUR = 3_600_000L;

	/**
	 * Game ticks counted towards the session clock. Which ticks qualify is the plugin's decision,
	 * so a session paused at the bank does not flatter the hourly rates.
	 */
	private int trackedTicks;

	private int catches;
	/**
	 * Trails which ended without the herbiboar being harvested.
	 */
	private int trailsLost;

	private long lootValue;
	private int hunterXp;

	private final Map<Integer, Integer> loot = new LinkedHashMap<>();

	private int totalTrailTicks;
	/**
	 * Catches whose trail was watched from the very start, and so contribute a usable duration.
	 */
	private int timedTrails;
	private int lastTrailTicks = -1;
	private int bestTrailTicks = -1;
	private int bestTrailSpots;

	/**
	 * Ticks spent stood still mid-trail, past whatever grace the player configured.
	 */
	/**
	 * Actual and theoretical-best ticks summed over trails that were timed end to end, which
	 * between them give how far off the quickest possible route the player is running.
	 */
	private int routeActualTicks;
	private int routeMinimumTicks;
	private int lastAboveMinimum = -1;
	private int bestAboveMinimum = -1;

	private int lostTicks;
	/**
	 * Ticks spent mid-trail actually moving or searching.
	 */
	private int workedTicks;

	/**
	 * Ticks stood still between one trail finishing and the next starting - the run back to a start
	 * object, banking, or simply pausing. Kept apart from the mid-trail figure because it answers a
	 * different question: mid-trail idling is sloppy play, whereas this is turnaround time.
	 */
	private int betweenLostTicks;
	/**
	 * Ticks spent moving between trails.
	 */
	private int betweenWorkedTicks;

	void tick()
	{
		trackedTicks++;
	}

	void recordLostTick()
	{
		lostTicks++;
	}

	void recordWorkedTick()
	{
		workedTicks++;
	}

	void recordBetweenLostTick()
	{
		betweenLostTicks++;
	}

	void recordBetweenWorkedTick()
	{
		betweenWorkedTicks++;
	}

	/**
	 * @param trailTicks how long the trail took, or a negative value when the trail was already
	 *                   under way before the plugin could see it start and its duration would be
	 *                   misleading. The catch itself still counts either way.
	 * @param spots      search spots along the trail
	 */
	void recordCatch(int trailTicks, int spots)
	{
		catches++;

		if (trailTicks < 0)
		{
			return;
		}

		timedTrails++;
		lastTrailTicks = trailTicks;
		totalTrailTicks += trailTicks;

		if (bestTrailTicks < 0 || trailTicks < bestTrailTicks)
		{
			bestTrailTicks = trailTicks;
			bestTrailSpots = spots;
		}
	}

	void recordTrailLost()
	{
		trailsLost++;
	}

	/**
	 * Files a completed trail against the quickest it could have been run.
	 *
	 * @param actualTicks  how long the trail took
	 * @param minimumTicks the same trail walked perfectly: straight to each revealed spot at
	 *                     running pace, with only the unavoidable search and reaction ticks
	 */
	void recordRoute(int actualTicks, int minimumTicks)
	{
		if (actualTicks < 0 || minimumTicks <= 0)
		{
			return;
		}

		routeActualTicks += actualTicks;
		routeMinimumTicks += minimumTicks;

		lastAboveMinimum = Math.max(0, actualTicks - minimumTicks);

		if (bestAboveMinimum < 0 || lastAboveMinimum < bestAboveMinimum)
		{
			bestAboveMinimum = lastAboveMinimum;
		}
	}

	/**
	 * Ticks spent above the theoretical best across every timed trail, or -1 with none yet.
	 */
	int getAboveMinimumTicks()
	{
		return routeMinimumTicks == 0 ? -1 : routeActualTicks - routeMinimumTicks;
	}

	/**
	 * The theoretical best as a share of what was actually run. 100% is a perfect session.
	 */
	int getRouteEfficiencyPercent()
	{
		return routeActualTicks == 0 ? -1 : Math.round(100f * routeMinimumTicks / routeActualTicks);
	}

	void addLoot(int itemId, int quantity, long value)
	{
		loot.merge(itemId, quantity, Integer::sum);
		lootValue += value;
	}

	void addHunterXp(int xp)
	{
		hunterXp += xp;
	}

	Map<Integer, Integer> getLoot()
	{
		return Collections.unmodifiableMap(loot);
	}

	long getDurationMillis()
	{
		return (long) trackedTicks * Constants.GAME_TICK_LENGTH;
	}

	boolean isStarted()
	{
		return trackedTicks > 0;
	}

	int getCatchesPerHour()
	{
		return (int) perHour(catches);
	}

	long getGpPerHour()
	{
		return (long) perHour(lootValue);
	}

	int getHunterXpPerHour()
	{
		return (int) perHour(hunterXp);
	}

	/**
	 * Mean length of a completed trail, in ticks, or -1 until one has been timed end to end.
	 */
	int getAverageTrailTicks()
	{
		return timedTrails == 0 ? -1 : Math.round((float) totalTrailTicks / timedTrails);
	}

	long getAverageLootValue()
	{
		return catches == 0 ? 0 : lootValue / catches;
	}

	/**
	 * Share of mid-trail ticks that were not spent stood still, as a percentage. -1 until a trail
	 * has actually been walked.
	 */
	int getEfficiencyPercent()
	{
		int total = workedTicks + lostTicks;
		return total == 0 ? -1 : Math.round(100f * workedTicks / total);
	}

	/**
	 * Ticks stood still across the whole session, mid-trail idling and turnaround between trails
	 * added together.
	 */
	int getSessionLostTicks()
	{
		return lostTicks + betweenLostTicks;
	}

	/**
	 * As {@link #getEfficiencyPercent()} but over every tracked tick, so the run back to a start
	 * object counts against it too.
	 */
	int getSessionEfficiencyPercent()
	{
		int total = workedTicks + lostTicks + betweenWorkedTicks + betweenLostTicks;
		return total == 0 ? -1 : Math.round(100f * (workedTicks + betweenWorkedTicks) / total);
	}

	float getLostTicksPerCatch()
	{
		return catches == 0 ? 0f : (float) lostTicks / catches;
	}

	private double perHour(double amount)
	{
		long millis = getDurationMillis();
		return millis <= 0 ? 0d : amount * MILLIS_PER_HOUR / millis;
	}
}

