package com.yonwiplugins.herbistats;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class HerbiStatsSessionTest
{
	/**
	 * 600ms per tick, so this many ticks is exactly one hour of session clock.
	 */
	private static final int TICKS_PER_HOUR = 6000;

	private final HerbiStatsSession session = new HerbiStatsSession();

	private void runClock(int ticks)
	{
		for (int i = 0; i < ticks; i++)
		{
			session.tick();
		}
	}

	@Test
	public void freshSessionReportsNothing()
	{
		assertEquals(0, session.getCatches());
		assertEquals(0, session.getDurationMillis());
		assertEquals(0, session.getCatchesPerHour());
		assertEquals(0, session.getGpPerHour());
		assertEquals(-1, session.getAverageTrailTicks());
		assertEquals(-1, session.getEfficiencyPercent());
		assertEquals(0f, session.getLostTicksPerCatch(), 0.0001f);
		assertTrue(session.getLoot().isEmpty());
	}

	@Test
	public void durationFollowsTheTickCount()
	{
		runClock(TICKS_PER_HOUR);
		assertEquals(3_600_000L, session.getDurationMillis());
		assertTrue(session.isStarted());
	}

	@Test
	public void ratesAreScaledToTheHour()
	{
		runClock(TICKS_PER_HOUR / 2);

		for (int i = 0; i < 30; i++)
		{
			session.recordCatch(100, 4);
			session.addLoot(199, 1, 5_000L);
		}

		session.addHunterXp(60_000);

		// Half an hour of work, so every rate doubles.
		assertEquals(60, session.getCatchesPerHour());
		assertEquals(300_000L, session.getGpPerHour());
		assertEquals(120_000, session.getHunterXpPerHour());
	}

	@Test
	public void ratesStayAtZeroBeforeTheClockStarts()
	{
		session.recordCatch(100, 4);
		session.addLoot(199, 1, 5_000L);

		assertEquals(0, session.getCatchesPerHour());
		assertEquals(0L, session.getGpPerHour());
	}

	@Test
	public void bestTrailKeepsTheFastestAndItsSpotCount()
	{
		session.recordCatch(120, 5);
		session.recordCatch(88, 3);
		session.recordCatch(140, 4);

		assertEquals(88, session.getBestTrailTicks());
		assertEquals(3, session.getBestTrailSpots());
		assertEquals(140, session.getLastTrailTicks());
		assertEquals(116, session.getAverageTrailTicks());
		assertEquals(3, session.getCatches());
	}

	@Test
	public void untimedCatchCountsButDoesNotSkewTimings()
	{
		session.recordCatch(100, 4);
		session.recordCatch(-1, 4);

		assertEquals(2, session.getCatches());
		assertEquals(100, session.getBestTrailTicks());
		assertEquals(100, session.getLastTrailTicks());
		assertEquals(100, session.getAverageTrailTicks());
	}

	@Test
	public void untimedCatchAloneLeavesTimingsUnset()
	{
		session.recordCatch(-1, 4);

		assertEquals(1, session.getCatches());
		assertEquals(-1, session.getBestTrailTicks());
		assertEquals(-1, session.getLastTrailTicks());
		assertEquals(-1, session.getAverageTrailTicks());
	}

	@Test
	public void efficiencyIsTheWorkedShareOfTrailTicks()
	{
		for (int i = 0; i < 90; i++)
		{
			session.recordWorkedTick();
		}

		for (int i = 0; i < 10; i++)
		{
			session.recordLostTick();
		}

		assertEquals(90, session.getEfficiencyPercent());
		assertEquals(10, session.getLostTicks());
		assertEquals(90, session.getWorkedTicks());
	}

	@Test
	public void lostTicksPerCatchAveragesOverCatches()
	{
		for (int i = 0; i < 15; i++)
		{
			session.recordLostTick();
		}

		session.recordCatch(100, 4);
		session.recordCatch(110, 4);

		assertEquals(7.5f, session.getLostTicksPerCatch(), 0.0001f);
	}

	@Test
	public void lootStacksPerItemAndSumsValue()
	{
		session.addLoot(199, 2, 2_000L);
		session.addLoot(201, 1, 3_500L);
		session.addLoot(199, 3, 3_000L);

		assertEquals(2, session.getLoot().size());
		assertEquals(Integer.valueOf(5), session.getLoot().get(199));
		assertEquals(Integer.valueOf(1), session.getLoot().get(201));
		assertEquals(8_500L, session.getLootValue());
	}

	@Test
	public void averageLootIsPerCatch()
	{
		session.addLoot(199, 1, 9_000L);
		session.recordCatch(100, 4);
		session.recordCatch(100, 4);

		assertEquals(4_500L, session.getAverageLootValue());
	}

	@Test
	public void lostTrailsAreCountedSeparatelyFromCatches()
	{
		session.recordCatch(100, 4);
		session.recordTrailLost();
		session.recordTrailLost();

		assertEquals(1, session.getCatches());
		assertEquals(2, session.getTrailsLost());
	}
}
